<script lang="ts">
import {onMount} from 'svelte';import type {Catalog,Locale} from './locales';import Select from './components/Select.svelte';import Toggle from './components/Toggle.svelte';import LogArchive from './LogArchive.svelte';
let {t,locale,request,consoleAllowed,logsAllowed,archive=$bindable(false)}=$props<{t:Catalog;locale:Locale;request:(url:string,body?:object)=>Promise<any>;consoleAllowed:boolean;logsAllowed:boolean;archive?:boolean}>();
type Line={seq:number;streamId:string;sourceSeq:number|null;source:string;module:string;text:string;receivedAt:string};
let rows=$state<Line[]>([]),source=$state('console'),module=$state(''),search=$state(''),history=$state(false),paused=$state(false),follow=$state(true),gap=$state(0),error=$state(''),loading=$state(false),switching=$state(false),cursor=0,generation=0,streamId='';let output=$state<HTMLTextAreaElement>();let autoPaused=false;
let sources=$derived([...(consoleAllowed&&logsAllowed?[{value:'all',label:t.allSources}]:[]),...(consoleAllowed?[{value:'console',label:t.consoleSource}]:[]),...(logsAllowed?[{value:'log',label:t.logSourceName},{value:'panel',label:t.panelSource}]:[])]);
let modules=$derived([{value:'',label:t.allModules},...[...new Set(rows.filter(x=>x.source==='console'?consoleAllowed:logsAllowed).map(x=>x.module).filter(Boolean))].sort().map(x=>({value:x,label:x}))]);
let filtered=$derived(rows.filter(x=>(x.source==='console'?consoleAllowed:logsAllowed)&&(!module||x.module===module)&&(!search||x.text.toLocaleLowerCase(locale).includes(search.toLocaleLowerCase(locale)))));
let text=$derived(filtered.map(x=>`[${new Date(x.receivedAt).toLocaleTimeString(locale)}] ${history?x.streamId.slice(0,8)+' ':''}${x.source}${x.module?' / '+x.module:''} #${x.sourceSeq??x.seq} ${x.text}`).join('\n')||t.emptyDiagnostic);
function reset(value?:string){switching=true;if(value!==undefined)source=value;generation++;cursor=0;rows=[];gap=0;error='';load();}
async function load(){if(loading||paused||(!consoleAllowed&&!logsAllowed))return;const gen=generation;loading=true;
try{for(let page=0;page<4;page++){const data=await request(`/api/diagnostics?cursor=${cursor}&source=${encodeURIComponent(source)}&history=${history}`);if(gen!==generation)return;if(data.streamId&&data.streamId!==streamId){rows=[];gap=0;streamId=data.streamId;}cursor=data.cursor;gap+=data.dropped;rows=[...rows,...data.lines].slice(-2000);if(data.lines.length<500)break;}error='';if(follow)requestAnimationFrame(()=>{if(output)output.scrollTop=output.scrollHeight;});}catch(e){error=(e as Error).message;}finally{loading=false;switching=false;}}
function onscroll(){if(!output)return;const atBottom=output.scrollHeight-output.scrollTop-output.clientHeight<24;if(!atBottom&&follow){follow=false;autoPaused=true;}else if(atBottom&&autoPaused){follow=true;autoPaused=false;}}
function latest(){follow=true;autoPaused=false;if(output)output.scrollTop=output.scrollHeight;}
function download(){const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='blackice-diagnostics.txt';a.click();URL.revokeObjectURL(url);}
onMount(()=>{load();const timer=setInterval(load,1000);return()=>{generation++;clearInterval(timer);};});
$effect(()=>{if(!sources.some(x=>x.value===source)){source=consoleAllowed?'console':'log';reset();}});
</script>
<div class="diagnostic-controls" class:archived={archive}><Select value={source} options={sources} label={t.logSource} onchange={reset} disabled={switching}/><Select value={module} options={modules} label={t.logModule} onchange={v=>module=v}/><label class="log-search"><span class="sr-only">{t.logSearch}</span><input bind:value={search} placeholder={t.logSearch} maxlength="256"/></label><button onclick={()=>{paused=!paused;if(!paused)load();}}>{paused?t.resumeLogs:t.pauseLogs}</button><button disabled={!filtered.length} onclick={download}>{t.exportLogs}</button><button class="archive-toggle" onclick={()=>archive=!archive}>{archive?t.liveStream:t.logArchive}</button></div>{#if archive}<LogArchive {t} {locale} {request}/>{:else}<div class="diagnostic-options"><Toggle checked={follow} label={t.follow} onchange={v=>{follow=v;autoPaused=false;if(v)latest();}}/><Toggle checked={history} label={t.logHistory} disabled={switching} onchange={v=>{history=v;reset();}}/><span class="muted">{t.receivedAt}</span></div>{#if gap||paused}<p class="stream-feedback" role="status">{paused?t.logPaused:t.logGap}</p>{/if}{#if error}<p class="error stream-feedback" role="alert">{t.errors[error as keyof typeof t.errors]??t.errors['request.failed']}</p>{/if}<div class="console-wrap"><textarea class="console-output" bind:this={output} onscroll={onscroll} readonly aria-label={t.diagnostics} value={(!consoleAllowed&&!logsAllowed)?t.noAccess:text}></textarea>{#if !follow}<button class="jump-latest" onclick={latest}>{t.jumpLatest} ↓</button>{/if}</div>{/if}
